	" . ( method_exists( $this->registry->getClass('output')->getTemplate('global'), 'userSmallPhoto' ) ? $this->registry->getClass('output')->getTemplate('global')->userSmallPhoto(array_merge( $member, array( '_customClass' => 'ipsUserPhoto_large' ) )) : '' ) . "
</div>";
return $IPBHTML;
}

